[CmdletBinding()]
param(
 [Parameter(Mandatory)][string]$EvidenceDirectory,
 [Parameter(Mandatory)][string]$IdentityPath,
 [Parameter(Mandatory)][string]$CandidateProofPath,
 [Parameter(Mandatory)][string]$EndCandidateProofPath,
 [Parameter(Mandatory)][string]$ExpectedRunId,
 [Parameter(Mandatory)][int]$ExpectedAttempt,
 [Parameter(Mandatory)][string]$ExpectedCandidate,
 [Parameter(Mandatory)][string]$ExpectedCodeIdentity,
 [Parameter(Mandatory)][string]$ExpectedWorkflowRef,
 [Parameter(Mandatory)][string]$ExpectedEventName,
 [Parameter(Mandatory)][string]$ExpectedAction
)
$ErrorActionPreference='Stop'; [Console]::OutputEncoding=[Text.UTF8Encoding]::new($false); $utf8=[Text.UTF8Encoding]::new($false,$true)
function Fail([string]$Message,[string]$Kind='proof'){ throw "[full-proof:$Kind] $Message" }
function Read-Json([string]$Path,[string]$Name) {
 if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){Fail "$Name is missing." 'missing'}
 try { $text=[IO.File]::ReadAllText([IO.Path]::GetFullPath($Path),$utf8); $v=$text|ConvertFrom-Json -Depth 100 -NoEnumerate -DateKind String } catch {Fail "$Name is not strict UTF-8 JSON: $($_.Exception.Message)" 'type'}
 if($null -eq $v -or $v -is [array] -or $v -isnot [pscustomobject]){Fail "$Name root must be an object." 'type'}; return $v
}
function Prop($Object,[string]$Name,[string]$Kind='proof') { $p=$Object.PSObject.Properties[$Name]; if($null -eq $p){Fail "Missing $Name." $Kind}; return ,$p.Value }
function String-Value($Object,[string]$Name) { $v=Prop $Object $Name 'type'; if($v -isnot [string] -or [string]::IsNullOrWhiteSpace($v)){Fail "$Name must be a nonempty string." 'type'}; return $v }
function Number($Object,[string]$Name,[bool]$Positive=$false) { $v=Prop $Object $Name 'type'; if($v -is [bool] -or $v -isnot [ValueType] -or [Type]::GetTypeCode($v.GetType()) -notin @([TypeCode]::Byte,[TypeCode]::SByte,[TypeCode]::Int16,[TypeCode]::UInt16,[TypeCode]::Int32,[TypeCode]::UInt32,[TypeCode]::Int64,[TypeCode]::UInt64,[TypeCode]::Single,[TypeCode]::Double,[TypeCode]::Decimal) -or [double]::IsNaN([double]$v) -or [double]::IsInfinity([double]$v) -or ($Positive -and $v -lt 1)){Fail "$Name must be a JSON number." 'type'}; return $v }
function Integer($Object,[string]$Name,[bool]$Positive=$false) { $v=Number $Object $Name $Positive; if([double]$v -ne [Math]::Truncate([double]$v)){Fail "$Name must be an integer." 'type'}; return $v }
function Array-Value($Object,[string]$Name,[string]$Kind='identity') { $v=Prop $Object $Name $Kind; if($v -isnot [array]){Fail "$Name must be an array." $Kind}; return ,$v }
function Bool($Object,[string]$Name) { $v=Prop $Object $Name 'type'; if($v -isnot [bool]){Fail "$Name must be Boolean." 'type'}; return $v }
function Owned([string]$Path,[string]$Root) { $full=[IO.Path]::GetFullPath($Path,$Root); $rel=[IO.Path]::GetRelativePath($Root,$full); if($rel -eq '..' -or $rel.StartsWith('..'+[IO.Path]::DirectorySeparatorChar) -or [IO.Path]::IsPathRooted($rel)){Fail "Evidence path escapes owned root: $Path" 'artifact'}; return $full }
function Relative-Owned([string]$Path,[string]$Root) { $full=Owned $Path $Root; return ([IO.Path]::GetRelativePath($Root,$full) -replace '\\','/') }
function Sha([string]$Path){ if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){Fail "Artifact is missing: $Path" 'artifact'}; return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash }
function Same([object]$A,[object]$B,[string]$Name){if($A -cne $B){Fail "$Name does not match current context." 'identity'}}
$root=[IO.Path]::GetFullPath($EvidenceDirectory)
$id=Read-Json $IdentityPath 'identity'; $proof=Read-Json $CandidateProofPath 'candidate proof'; $end=Read-Json $EndCandidateProofPath 'end candidate proof'
Same (String-Value $id 'sha') $ExpectedCodeIdentity 'identity code'; Same (String-Value $id 'checkout') $ExpectedCodeIdentity 'identity checkout'; Same (String-Value $id 'candidate') $ExpectedCandidate 'identity candidate'; Same (String-Value $id 'runId') $ExpectedRunId 'identity run'; if((Integer $id 'attempt' $true) -ne $ExpectedAttempt){Fail 'Identity attempt does not match.' 'identity'}
foreach($nameAndExpected in @(@('workflowRef',$ExpectedWorkflowRef),@('eventName',$ExpectedEventName),@('action',$ExpectedAction))){Same (String-Value $id $nameAndExpected[0]) $nameAndExpected[1] "identity $($nameAndExpected[0])"}
$expectedMode=if($ExpectedEventName -eq 'pull_request'){'ready-full'}elseif($ExpectedEventName -eq 'push'){'push-main'}elseif($ExpectedEventName -eq 'workflow_dispatch'){'manual-full'}else{Fail 'Unsupported expected event.' 'identity'}; $expectedAction=if($ExpectedEventName -eq 'push'){'main'}else{$ExpectedAction}; foreach($c in @($proof,$end)){Same (String-Value $c 'runId') $ExpectedRunId 'candidate run'; if((Integer $c 'runAttempt' $true) -ne $ExpectedAttempt){Fail 'Candidate attempt does not match.' 'identity'}; Same (String-Value $c 'candidateSha') $ExpectedCandidate 'candidate SHA'; Same (String-Value $c 'actualCheckout') $ExpectedCodeIdentity 'candidate checkout'; Same (String-Value $c 'workflowRef') $ExpectedWorkflowRef 'candidate workflow'; Same (String-Value $c 'eventName') $ExpectedEventName 'candidate event'; Same (String-Value $c 'action') $expectedAction 'candidate action'; Same (String-Value $c 'mode') $expectedMode 'candidate mode'; if((Bool $c 'draft')){Fail 'Full candidate cannot be draft.' 'identity'}; [void](String-Value $c 'tree'); $parents=Array-Value $c 'parents'; if($expectedMode -eq 'ready-full'){if($parents.Count -ne 2){Fail 'PR candidate requires exactly two ordered parents.' 'identity'}; Same (String-Value $c 'baseSha') ([string]$parents[0]) 'PR base'; Same (String-Value $c 'headSha') ([string]$parents[1]) 'PR head'}else{if($null -ne $c.headSha -or $null -ne $c.baseSha){Fail 'Non-PR candidate head/base must be null.' 'identity'}}}; if((String-Value $proof 'tree') -cne (String-Value $end 'tree')){Fail 'Candidate start/end tree differs.' 'identity'}; $p1=Array-Value $proof 'parents';$p2=Array-Value $end 'parents';if($p1.Count -ne $p2.Count){Fail 'Candidate start/end parent count differs.' 'identity'};for($i=0;$i -lt $p1.Count;$i++){Same ([string]$p1[$i]) ([string]$p2[$i]) 'candidate ordered parents'}
$measurement=Read-Json (Join-Path $root 'm0-evidence/task-measurement.json') 'task measurement'; if((Number $measurement 'schemaVersion') -ne 1 -or -not(Bool $measurement 'measured')){Fail 'Measurement is not schemaVersion 1 measured evidence.' 'measurement'}; Same (String-Value $measurement 'runId') "gha-${ExpectedRunId}-${ExpectedAttempt}" 'measurement run'; if((Integer $measurement 'runAttempt' $true) -ne $ExpectedAttempt){Fail 'Measurement attempt mismatch.' 'measurement'}; Same (String-Value $measurement 'codeIdentity') $ExpectedCodeIdentity 'measurement code'; if((Bool $measurement 'exitKnown') -ne $true){Fail 'Measurement exit is unknown.' 'measurement'}; if((Number $measurement 'exitCode') -ne 0){Fail 'Original task exit was nonzero.' 'original-task'}; $wall=[double](Number $measurement 'wallClockMs'); if($wall -le 0){Fail 'Measurement wall clock is negative.' 'measurement'}
$start=[DateTimeOffset]::MinValue;$finish=[DateTimeOffset]::MinValue;$startText=String-Value $measurement 'startedUtc';$finishText=String-Value $measurement 'finishedUtc';if($startText -notmatch '(Z|[+-]\d{2}:\d{2})$' -or $finishText -notmatch '(Z|[+-]\d{2}:\d{2})$' -or -not[DateTimeOffset]::TryParse($startText,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$start) -or -not[DateTimeOffset]::TryParse($finishText,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$finish) -or $finish -lt $start){Fail 'Measurement time envelope requires explicit time zones and ordered instants.' 'measurement'}
$taskExitPath=Join-Path $root 'm0-evidence/task-exit.txt'; if(-not(Test-Path -LiteralPath $taskExitPath -PathType Leaf)){Fail 'Original task-exit evidence is missing.' 'original-task'}; if(([IO.File]::ReadAllText($taskExitPath,$utf8)).Trim() -cne '0'){Fail 'task-exit.txt is not numeric zero.' 'original-task'}
$m0=Join-Path $root 'm0-evidence'
$measurementRoot=String-Value $measurement 'evidenceDirectory'
if(-not[IO.Path]::IsPathRooted($measurementRoot) -or -not[string]::Equals([IO.Path]::GetFullPath($measurementRoot),$m0,$(if($IsWindows){[StringComparison]::OrdinalIgnoreCase}else{[StringComparison]::Ordinal}))){Fail 'Measurement is not bound to the current M0 evidence root.' 'measurement'}
$captureErrors=$measurement.PSObject.Properties['captureErrors'];if($null -ne $captureErrors -and ($captureErrors.Value -isnot [array] -or $captureErrors.Value.Count -ne 0)){Fail 'Original evidence capture was incomplete.' 'measurement'}
$costInputPath=Join-Path $m0 'cost-input.json'; $commandsPath=Join-Path $m0 'commands.json'; $cost=Read-Json (Join-Path $m0 'cost-report.json') 'cost report'; if((Number $cost 'schemaVersion') -ne 1 -or (String-Value $cost 'evidenceKind') -cne 'measured' -or (String-Value $cost 'reportStatus') -cne 'generated' -or (Number $cost 'toolExitCode') -ne 0){Fail 'Cost report status/schema is invalid.' 'cost'}; Same (String-Value $cost 'runId') "gha-${ExpectedRunId}-${ExpectedAttempt}" 'cost run'; Same (String-Value $cost.context 'codeIdentity') $ExpectedCodeIdentity 'cost code'; $costInput=Read-Json $costInputPath 'cost input'; if((Number $costInput 'schemaVersion') -ne 1 -or (String-Value $costInput 'evidenceKind') -cne 'measured' -or (String-Value $costInput 'runId') -cne "gha-${ExpectedRunId}-${ExpectedAttempt}"){Fail 'Cost input schema/identity is stale.' 'cost'}; Same (String-Value $costInput.context 'codeIdentity') $ExpectedCodeIdentity 'cost input code'; if((String-Value $costInput 'commandsPath') -cne $commandsPath){Fail 'Cost input commandsPath is not current m0 index.' 'cost'}; if((Number $costInput.task 'exitCode') -ne 0 -or [double](Number $costInput.task 'wallClockMs') -ne $wall){Fail 'Cost input task measurement mismatch.' 'cost'}; $task=$cost.taskResult; if((Number $task 'exitCode') -ne 0 -or (String-Value $task 'completion') -cne 'completed' -or (String-Value $task 'status') -notin @('success','completed-with-expected-failures')){Fail 'Cost task result is not a complete successful task.' 'cost'}; if([double](Number $task 'wallClockMs') -ne $wall){Fail 'Cost wall clock is not the measured wall clock.' 'cost'}
$commands=Array-Value $cost 'commands' 'cost'; if(!$commands.Count){Fail 'Cost report has no commands.' 'ledger'}; foreach($cmd in $commands){$r=$cmd.originalRecord;$cs=[DateTimeOffset]::MinValue;$cf=[DateTimeOffset]::MinValue;if($null -eq $r -or -not[DateTimeOffset]::TryParse((String-Value $r 'startedUtc'),[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$cs) -or -not[DateTimeOffset]::TryParse((String-Value $r 'finishedUtc'),[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$cf) -or $cf -lt $cs -or $cs -lt $start -or $cf -gt $finish){Fail 'Command time is outside measured outer envelope.' 'measurement'}}; $required=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase); foreach($p in @('commands.json','PASS.txt','task-exit.txt')){[void]$required.Add($p)}; foreach($cmd in $commands){$r=$cmd.originalRecord;if($null -eq $r -or [string]::IsNullOrWhiteSpace([string]$r.log)){Fail 'Command lacks original log binding.' 'ledger'}; foreach($p in @($r.log,$r.stdout,$r.stderr)){if($p){[void]$required.Add((Relative-Owned ([string]$p) $m0))}}; foreach($trx in @($cmd.trx)){if($null -eq $trx.artifact){Fail 'Command lacks TRX artifact binding.' 'ledger'}; [void]$required.Add((Relative-Owned ([string]$trx.artifact.path) $m0))}}
$artifacts=Array-Value $measurement 'artifacts' 'measurement'; if(!$artifacts.Count){Fail 'Measurement artifact snapshot is empty.' 'measurement'}; $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase); foreach($a in $artifacts){$path=String-Value $a 'path';$full=Owned $path $m0;$rel=[IO.Path]::GetRelativePath($m0,$full) -replace '\\','/';if(-not$seen.Add($rel)){Fail "Duplicate measurement artifact: $rel" 'artifact'};if((String-Value $a 'sha256') -notmatch '^[0-9A-Fa-f]{64}$'){Fail 'Artifact SHA256 is invalid.' 'type'};if((Integer $a 'length') -ne ([IO.FileInfo]$full).Length -or (String-Value $a 'sha256') -cne (Sha $full)){Fail "Artifact snapshot mismatch: $rel" 'artifact'}}; foreach($needed in $required){if(-not$seen.Contains($needed)){Fail "Measurement does not bind required artifact: $needed" 'artifact'}}
$inputPath=$costInputPath; if(-not(Test-Path -LiteralPath $inputPath -PathType Leaf)){Fail 'Cost input is missing.' 'cost'}; $stored=Get-Content -LiteralPath (Join-Path $m0 'cost-report.json') -Raw; $pwsh=(Get-Command pwsh -CommandType Application -ErrorAction Stop|Select-Object -First 1).Source; $psi=[Diagnostics.ProcessStartInfo]::new($pwsh);$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.StandardOutputEncoding=$utf8;$psi.StandardErrorEncoding=$utf8;foreach($arg in @('-NoProfile','-File',(Join-Path $PSScriptRoot 'Get-TestCostReport.ps1'),'-InputPath',$inputPath)){$null=$psi.ArgumentList.Add($arg)};$proc=[Diagnostics.Process]::new();$proc.StartInfo=$psi;if(-not$proc.Start()){Fail 'Could not start cost report reader.' 'cost'};$stdout=$proc.StandardOutput.ReadToEndAsync();$stderr=$proc.StandardError.ReadToEndAsync();$proc.WaitForExit();$toolOut=$stdout.GetAwaiter().GetResult();$toolErr=$stderr.GetAwaiter().GetResult();$toolExit=$proc.ExitCode;$proc.Dispose();if($toolExit -ne 0 -or [string]::IsNullOrWhiteSpace($toolOut)){Fail "Cost report regeneration failed with exit ${toolExit}: $toolErr" 'cost'}; try{$actual=[Text.Json.Nodes.JsonNode]::Parse($toolOut);$expected=[Text.Json.Nodes.JsonNode]::Parse($stored)}catch{Fail "Cost report output is not JSON: $($_.Exception.Message)" 'cost'};if(-not[Text.Json.Nodes.JsonNode]::DeepEquals($actual,$expected)){Fail 'Stored cost report differs from read-only regeneration.' 'cost'}
[ordered]@{status='complete';runId=$ExpectedRunId;runAttempt=$ExpectedAttempt;candidateSha=$ExpectedCandidate;codeIdentity=$ExpectedCodeIdentity;identityPath=$IdentityPath;candidateProofPath=$CandidateProofPath;endCandidateProofPath=$EndCandidateProofPath;costReport='m0-evidence/cost-report.json'}|ConvertTo-Json -Compress
